fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    assert_eq!(s2.len(), n, "All input vectors must have the same length");
    assert_eq!(s3.len(), n, "All input vectors must have the same length");

    // Pre-allocate a vector of size 3 * n
    let mut res = Vec::with_capacity(3 * n);

    // Interleave elements index by index
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}

